const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Australia and Indonesia
  const australia = ee.Geometry.Rectangle([113, -44, 154, -10]);
  const indonesia = ee.Geometry.Rectangle([95, -11, 141, 6]);

  // 2. Define time period
  const startDate = '2024-10-01';
  const endDate = '2024-10-31';

  // 3. Load Sentinel-5P CO data
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .select(['CO_column_number_density', 'qa_value'])
    .filterDate(startDate, endDate);

  const australiaCol = collection.filterBounds(australia);
  const indonesiaCol = collection.filterBounds(indonesia);

  const ausSize = australiaCol.size().getInfo();
  const indoSize = indonesiaCol.size().getInfo();

  console.log(`Australia images: ${ausSize}`);
  console.log(`Indonesia images: ${indoSize}`);

  // Check if either collection is empty
  if (ausSize === 0 || indoSize === 0) {
    console.log("No data found for one or both locations");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create composite with QA filtering
  function maskCO(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.5);
    return image.select('CO_column_number_density').updateMask(mask);
  }

  const australiaMean = australiaCol.map(maskCO).mean();
  const indonesiaMean = indonesiaCol.map(maskCO).mean();

  // 5. Calculate mean CO concentration with pixel count
  const ausStats = australiaMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: australia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const indoStats = indonesiaMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: indonesia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const ausCO = ausStats['CO_column_number_density_mean'];
  const ausCount = ausStats['CO_column_number_density_count'];
  const indoCO = indoStats['CO_column_number_density_mean'];
  const indoCount = indoStats['CO_column_number_density_count'];

  console.log(`Australia: CO=${ausCO}, Pixels=${ausCount}`);
  console.log(`Indonesia: CO=${indoCO}, Pixels=${indoCount}`);

  // 6. Check for valid pixels
  if (ausCount === 0 || indoCount === 0) {
    console.log("No valid pixels after QA filtering");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Validate results
  if (ausCO == null || indoCO == null || isNaN(ausCO) || isNaN(indoCO) || 
      ausCO < 0 || indoCO < 0 || ausCO > 1 || indoCO > 1) {
    console.log("Invalid CO values detected");
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Compare and provide answer
  console.log(`Australia CO: ${(ausCO * 1e6).toFixed(2)} µmol/m²`);
  console.log(`Indonesia CO: ${(indoCO * 1e6).toFixed(2)} µmol/m²`);

  if (ausCO > indoCO) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
